//! Connector definition (design/connectors.md section 4): serde types, the
//! validator, and the built-in definitions embedded from `spec/connectors/`.

use serde::{Deserialize, Serialize};
use serde_json::Value;
use std::collections::HashSet;

// `BUILTIN_CONNECTOR_FILES`: every `spec/connectors/*.json` as (file name, text), sorted by file
// name. Generated by build.rs; adding a connector is adding a file.
include!(concat!(env!("OUT_DIR"), "/builtin_connectors.rs"));

/// The text of one built-in connector file (tests).
#[cfg(test)]
fn builtin_file(name: &str) -> &'static str {
    BUILTIN_CONNECTOR_FILES
        .iter()
        .find(|(file, _)| *file == name)
        .map(|(_, text)| *text)
        .unwrap_or_else(|| panic!("no built-in connector file {name}"))
}

/// Sentinel client id shipped in `spec/connectors/microsoft-365.json` until
/// the real Squrell Entra public client id exists. A node overrides it
/// (`VAMD_CONNECTOR_MICROSOFT_365_CLIENT_ID`); while it is still this value
/// the connector is not configured and Enable must answer 409.
pub const PLACEHOLDER_CLIENT_ID: &str = "PLACEHOLDER-squrell-entra-client-id";

pub const URN_PREFIX: &str = "urn:vam:connector:";

/// True when `client_id` is the shipped placeholder (or empty).
pub fn is_placeholder_client_id(client_id: &str) -> bool {
    let t = client_id.trim();
    t.is_empty() || t == PLACEHOLDER_CLIENT_ID
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct Connector {
    pub urn: String,
    pub version: String,
    pub display_name: String,
    pub publisher: String,
    pub description: String,
    pub icon: String,
    pub provider: Provider,
    pub connection: ConnectionSpec,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub bindings: Option<Vec<Binding>>,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub mcp: Option<McpServer>,
    /// Reserved (design 6.6): accepted, unused.
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub events: Option<Vec<Value>>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(tag = "kind", rename_all = "snake_case")]
pub enum Provider {
    Oauth2(OAuth2Provider),
    ApiKey(ApiKeyProvider),
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct OAuth2Provider {
    pub profile: OAuthProfile,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub client_id: Option<String>,
    pub client_secret: ClientSecret,
    pub scopes: Vec<String>,
    pub org_consent: OrgConsent,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum OAuthProfile {
    Entra,
    Discover,
    Google,
    Slack,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ClientSecret {
    None,
    SqurellRelay,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum OrgConsent {
    None,
    AdminRequired,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct ApiKeyProvider {
    pub fields: Vec<ApiKeyField>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct ApiKeyField {
    pub name: String,
    pub label: String,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct ConnectionSpec {
    pub holder: Holder,
    pub multi_account: bool,
    pub label: String,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Holder {
    User,
    Org,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct Binding {
    pub name: String,
    pub placeholder: String,
    pub value: BindingValue,
    pub inject: Inject,
    pub hosts: Vec<String>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum BindingValue {
    AccessToken,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum Inject {
    Bearer,
    Header,
    Query,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct McpServer {
    pub url: String,
    pub tools: Vec<McpTool>,
}

#[derive(Debug, Clone, PartialEq, Serialize, Deserialize)]
#[serde(deny_unknown_fields, rename_all = "camelCase")]
pub struct McpTool {
    pub remote: String,
    pub side_effect: SideEffect,
    #[serde(default, skip_serializing_if = "Option::is_none")]
    pub default: Option<ToolDefault>,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "SCREAMING_SNAKE_CASE")]
pub enum SideEffect {
    ReadOnly,
    MutableLocal,
    MutableExternal,
}

#[derive(Debug, Clone, Copy, PartialEq, Eq, Serialize, Deserialize)]
#[serde(rename_all = "snake_case")]
pub enum ToolDefault {
    Allow,
    Ask,
    Block,
}

#[derive(Debug, Clone, PartialEq, Eq, thiserror::Error)]
pub enum ConnectorError {
    #[error("connector json: {0}")]
    Parse(String),
    #[error("connector invalid: {0}")]
    Invalid(String),
}

fn bad<T>(m: impl Into<String>) -> Result<T, ConnectorError> {
    Err(ConnectorError::Invalid(m.into()))
}

/// Parse (unknown fields refused except `events`) and validate.
pub fn parse_connector(raw: &str) -> Result<Connector, ConnectorError> {
    let c: Connector =
        serde_json::from_str(raw).map_err(|e| ConnectorError::Parse(e.to_string()))?;
    validate_connector(&c)?;
    Ok(c)
}

pub(crate) fn valid_urn(urn: &str) -> bool {
    let Some(rest) = urn.strip_prefix(URN_PREFIX) else {
        return false;
    };
    let segs: Vec<&str> = rest.split('/').collect();
    segs.len() >= 2
        && segs.iter().all(|s| {
            !s.is_empty()
                && s.bytes()
                    .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b"-._".contains(&b))
        })
}

pub(crate) fn valid_host(h: &str) -> bool {
    !h.is_empty()
        && !h.starts_with('.')
        && !h.ends_with('.')
        && h.bytes()
            .all(|b| b.is_ascii_lowercase() || b.is_ascii_digit() || b == b'-' || b == b'.')
}

pub fn validate_connector(c: &Connector) -> Result<(), ConnectorError> {
    if !valid_urn(&c.urn) {
        return bad(format!("urn must be {URN_PREFIX}<host>/<publisher>/<name>"));
    }
    for (n, v) in [
        ("version", &c.version),
        ("displayName", &c.display_name),
        ("publisher", &c.publisher),
        ("icon", &c.icon),
        ("connection.label", &c.connection.label),
    ] {
        if v.trim().is_empty() {
            return bad(format!("{n} must not be empty"));
        }
    }
    match (c.bindings.is_some(), c.mcp.is_some()) {
        (true, false) | (false, true) => {}
        _ => return bad("exactly one of bindings and mcp is required"),
    }
    if c.connection.holder != Holder::User || c.connection.multi_account {
        return bad("version one allows only holder user with multiAccount false");
    }
    match &c.provider {
        Provider::Oauth2(p) => {
            if p.scopes.iter().any(|s| s.trim().is_empty()) {
                return bad("scopes must not contain an empty scope");
            }
            if p.profile == OAuthProfile::Entra {
                if p.org_consent != OrgConsent::AdminRequired {
                    return bad("entra requires orgConsent admin_required");
                }
                if !p.scopes.iter().any(|s| s == "offline_access") {
                    return bad("entra requires the offline_access scope");
                }
            }
        }
        Provider::ApiKey(p) => {
            if p.fields.is_empty() || p.fields.iter().any(|f| f.name.trim().is_empty()) {
                return bad("api_key needs named fields");
            }
        }
    }
    if let Some(bs) = &c.bindings {
        if bs.is_empty() {
            return bad("bindings must not be empty");
        }
        let mut names = HashSet::new();
        for b in bs {
            if b.name.trim().is_empty() || b.placeholder.trim().is_empty() {
                return bad("binding name and placeholder must not be empty");
            }
            if !names.insert(b.name.as_str()) {
                return bad(format!("duplicate binding name {}", b.name));
            }
            if b.hosts.is_empty() {
                return bad(format!("binding {} needs at least one host", b.name));
            }
            for h in &b.hosts {
                if !valid_host(h) {
                    return bad(format!(
                        "binding host {h:?} must be an exact lowercase host (no scheme, port, path or wildcard)"
                    ));
                }
            }
        }
    }
    if let Some(m) = &c.mcp {
        if !m.url.starts_with("https://") || m.url.len() <= "https://".len() {
            return bad("mcp.url must be an https url");
        }
        let mut seen = HashSet::new();
        for t in &m.tools {
            if t.remote.trim().is_empty() {
                return bad("mcp tool name must not be empty");
            }
            if !seen.insert(t.remote.as_str()) {
                return bad(format!("duplicate mcp tool {}", t.remote));
            }
        }
    }
    Ok(())
}

/// The built-in connector definitions, validated at call time.
pub fn builtin_connectors() -> Vec<Connector> {
    connectors_from_files(BUILTIN_CONNECTOR_FILES)
        .unwrap_or_else(|e| panic!("built-in connector definitions are not valid: {e}"))
}

/// Parse and validate connector files (file name, text), in the given order. A file that does
/// not validate, or a repeated URN or id, is an error naming the file.
pub fn connectors_from_files(files: &[(&str, &str)]) -> Result<Vec<Connector>, String> {
    let mut out: Vec<Connector> = Vec::new();
    for (file, raw) in files {
        let c = parse_connector(raw).map_err(|e| format!("{file}: {e}"))?;
        let id = c.urn.rsplit('/').next().unwrap_or_default().to_string();
        if out
            .iter()
            .any(|o| o.urn == c.urn || o.urn.rsplit('/').next().unwrap_or_default() == id)
        {
            return Err(format!("{file}: duplicate connector urn or id '{}'", c.urn));
        }
        out.push(c);
    }
    Ok(out)
}

#[cfg(test)]
mod tests {
    use super::*;
    use serde_json::json;

    fn m365() -> Value {
        serde_json::from_str(builtin_file("microsoft-365.json")).unwrap()
    }
    fn linear() -> Value {
        serde_json::from_str(builtin_file("linear.json")).unwrap()
    }
    fn err(v: Value) -> String {
        parse_connector(&v.to_string()).unwrap_err().to_string()
    }

    #[test]
    fn builtins_validate() {
        let all = builtin_connectors();
        assert_eq!(all.len(), BUILTIN_CONNECTOR_FILES.len());
        assert!(all.iter().any(|c| c.urn.ends_with("/microsoft-365")));
        assert!(all.iter().any(|c| c.urn.ends_with("/linear")));
        let names: Vec<&str> = BUILTIN_CONNECTOR_FILES.iter().map(|(n, _)| *n).collect();
        let mut sorted = names.clone();
        sorted.sort();
        assert_eq!(names, sorted, "embedded in file-name order");
    }

    #[test]
    fn a_new_file_is_listed_and_a_duplicate_or_invalid_one_is_refused() {
        let mut files: Vec<(&str, &str)> = BUILTIN_CONNECTOR_FILES.to_vec();
        let mut extra = m365();
        extra["urn"] = json!("urn:vam:connector:hub.squrell.cloud/squrell/extra-one");
        let extra = extra.to_string();
        files.push(("extra-one.json", &extra));
        let listed = connectors_from_files(&files).unwrap();
        assert_eq!(listed.len(), BUILTIN_CONNECTOR_FILES.len() + 1);
        assert!(listed.last().unwrap().urn.ends_with("/extra-one"));

        let dup = [
            ("a.json", builtin_file("linear.json")),
            ("b.json", builtin_file("linear.json")),
        ];
        assert!(connectors_from_files(&dup)
            .unwrap_err()
            .contains("b.json: duplicate"));
        let bad = [("bad.json", "{}")];
        assert!(connectors_from_files(&bad)
            .unwrap_err()
            .starts_with("bad.json:"));
    }

    #[test]
    fn placeholder_helper() {
        assert!(is_placeholder_client_id(PLACEHOLDER_CLIENT_ID));
        assert!(is_placeholder_client_id(" "));
        assert!(!is_placeholder_client_id(
            "11111111-2222-3333-4444-555555555555"
        ));
        let m365_def = builtin_connectors()
            .into_iter()
            .find(|c| c.urn.ends_with("/microsoft-365"))
            .unwrap();
        let Provider::Oauth2(p) = &m365_def.provider else {
            panic!()
        };
        // The built-in carries Squrell's real public client id (not a secret).
        assert!(!is_placeholder_client_id(
            p.client_id.as_deref().unwrap_or("")
        ));
        assert!(p.scopes.iter().any(|s| s == "profile"));
    }

    #[test]
    fn bad_urn() {
        let mut v = m365();
        v["urn"] = json!("urn:vam:skill:x/y");
        assert!(err(v).contains("urn"));
        let mut v = m365();
        v["urn"] = json!("urn:vam:connector:onlyone");
        assert!(err(v).contains("urn"));
    }

    #[test]
    fn both_or_neither_of_bindings_and_mcp() {
        let mut v = m365();
        v["mcp"] = linear()["mcp"].clone();
        assert!(err(v).contains("exactly one"));
        let mut v = m365();
        v.as_object_mut().unwrap().remove("bindings");
        assert!(err(v).contains("exactly one"));
    }

    #[test]
    fn entra_needs_admin_consent() {
        let mut v = m365();
        v["provider"]["orgConsent"] = json!("none");
        assert!(err(v).contains("admin_required"));
    }

    #[test]
    fn entra_needs_offline_access() {
        let mut v = m365();
        v["provider"]["scopes"] = json!(["openid", "User.Read"]);
        assert!(err(v).contains("offline_access"));
    }

    #[test]
    fn version_one_holder_and_multi_account() {
        let mut v = m365();
        v["connection"]["holder"] = json!("org");
        assert!(err(v).contains("version one"));
        let mut v = m365();
        v["connection"]["multiAccount"] = json!(true);
        assert!(err(v).contains("version one"));
    }

    #[test]
    fn duplicate_tool_names() {
        let mut v = linear();
        v["mcp"]["tools"]
            .as_array_mut()
            .unwrap()
            .push(json!({"remote":"get_issue","sideEffect":"READ_ONLY"}));
        assert!(err(v).contains("duplicate mcp tool"));
    }

    #[test]
    fn closed_side_effect_and_default_sets() {
        let mut v = linear();
        v["mcp"]["tools"][0]["sideEffect"] = json!("SOMETIMES");
        assert!(err(v).contains("connector json"));
        let mut v = linear();
        v["mcp"]["tools"][0]["default"] = json!("maybe");
        assert!(err(v).contains("connector json"));
    }

    #[test]
    fn binding_hosts_are_exact() {
        for h in [
            "*.microsoft.com",
            "https://graph.microsoft.com",
            "graph.microsoft.com:443",
            "graph.microsoft.com/v1.0",
            "Graph.Microsoft.com",
        ] {
            let mut v = m365();
            v["bindings"][0]["hosts"] = json!([h]);
            assert!(err(v).contains("exact lowercase host"), "{h}");
        }
    }

    #[test]
    fn unknown_fields_refused() {
        let mut v = m365();
        v["surprise"] = json!(1);
        assert!(err(v).contains("connector json"));
        let mut v = m365();
        v["provider"]["extra"] = json!(1);
        assert!(err(v).contains("connector json"));
        let mut v = linear();
        v["mcp"]["tools"][0]["extra"] = json!(1);
        assert!(err(v).contains("connector json"));
    }

    #[test]
    fn events_reserved_list_accepted() {
        let mut v = linear();
        v["events"] = json!([{"kind": "anything"}]);
        let c = parse_connector(&v.to_string()).unwrap();
        assert_eq!(c.events.as_ref().unwrap().len(), 1);
    }

    #[test]
    fn json_round_trip_is_stable() {
        for c in builtin_connectors() {
            let s = serde_json::to_string(&c).unwrap();
            let back: Connector = serde_json::from_str(&s).unwrap();
            assert_eq!(back, c);
            assert_eq!(serde_json::to_string(&back).unwrap(), s);
        }
    }
}
